  [94825] = { "Lampo disorientante", "Parla con la somma sacerdotessa Mims a ⟦Ironforge=Forgiardente⟧.", "Poco fa uno dei vostri sacerdoti è venuto a cercarti, {race}. Ha detto che, se ti avessi visto, avrei dovuto indirizzarti verso la Hall of Mysteries. Ha detto che era molto importante, ma al tuo posto non mi preoccuperei troppo. Sembrava di buon umore... come se si trattasse di buone notizie. Al tuo posto, però, non tarderei ad andarci.\n\nChe Elune sia con te, nobile {race}.", nil, nil, 0xd8782324, 0x656c5f67, 0xa819c88b, nil, nil, "...mm" },
  [94826] = { "Lampo disorientante", "Parla con la somma sacerdotessa Mims a ⟦Ironforge=Forgiardente⟧.", nil, nil, nil, 0xd8782324, 0x656c5f67, nil, nil, nil, "..mmm" },
