  [94913] = { "⟦Moonglade=Radaluna⟧", "Usa l'incantesimo \"⟦Teleport: Moonglade=Teletrasporto: Radaluna⟧\" per raggiungere ⟦Moonglade=Radaluna⟧. Al tuo arrivo, parla con Dendrite Starblaze nel villaggio di ⟦Nighthaven=Nottequieta⟧.", "Tutti i druidi sono i benvenuti nelle terre sacre di ⟦Moonglade=Radaluna⟧. Il custode Remulos, guardiano di ⟦Moonglade=Radaluna⟧, veglia su tutti i druidi che vi riposano. Ti insegnerò l'incantesimo che ti permette di trasportarti lì. Lancialo ogni volta che cerchi la conoscenza o il conforto di ⟦Moonglade=Radaluna⟧.\n\nQuanto alla tua prima lezione qui su Azeroth, recati a ⟦Moonglade=Radaluna⟧ e parla con Dendrite Starblaze a ⟦Nighthaven=Nottequieta⟧ del sentiero che ora percorri. Buona fortuna, giovane druido.", nil, "Ah, vedo che hai già padroneggiato la forma d'orso. Bene, bene. Sei sulla buona strada, giovane {class}.", 0xaeb97c8b, 0xf8085429, 0x89074bce, nil, 0x0e12a96b, "...m." },
  [94914] = { "⟦Moonglade=Radaluna⟧", "Usa l'incantesimo \"⟦Teleport: Moonglade=Teletrasporto: Radaluna⟧\" per raggiungere ⟦Moonglade=Radaluna⟧. Al tuo arrivo, parla con Dendrite Starblaze nel villaggio di ⟦Nighthaven=Nottequieta⟧.", "Tutti i druidi sono i benvenuti nelle terre sacre di ⟦Moonglade=Radaluna⟧. Il custode Remulos, guardiano di ⟦Moonglade=Radaluna⟧, veglia su tutti i druidi che vi riposano. Ti insegnerò l'incantesimo che ti permette di trasportarti lì. Lancialo ogni volta che cerchi la conoscenza o il conforto di ⟦Moonglade=Radaluna⟧.\n\nQuanto alla tua prima lezione qui su Azeroth, recati a ⟦Moonglade=Radaluna⟧ e parla con Dendrite Starblaze a ⟦Nighthaven=Nottequieta⟧ del sentiero che ora percorri. Buona fortuna, giovane druido.", nil, nil, 0xaeb97c8b, 0xf8085429, 0x89074bce, nil, nil, "...mm" },
  [94978] = { "Addomesticare la bestia", nil, nil, "Imparerai, {name}, e un giorno sarai <un/una> grande {class}.", nil, 0xecd97a9a, nil, nil, 0xe5057f89, nil, ".mm.m" },
